mapper.select:
SELECT


(
SELECT COALESCE(SUM(lr.duration_minutes), 0)
FROM studyhub.learning_records lr
JOIN studyhub.goals g ON lr.goal_id = g.id
WHERE g.user_id = #{userId}
) AS totalStudyMinutes,


(
SELECT COUNT(lr.id)
FROM studyhub.learning_records lr
JOIN studyhub.goals g ON lr.goal_id = g.id
WHERE g.user_id = #{userId}
) AS totalRecordCount,


(
SELECT COUNT(g.id)
FROM studyhub.goals g
WHERE g.user_id = #{userId}
) AS totalGoalCount,


(
SELECT COUNT(g.id)
FROM studyhub.goals g
WHERE g.user_id = #{userId}
AND g.completed_minutes >= g.target_minutes
) AS completedGoalCount,


(
SELECT COALESCE(SUM(g.target_minutes), 0)
FROM studyhub.goals g
WHERE g.user_id = #{userId}
) AS totalTargetMinutes,


(
SELECT COALESCE(SUM(g.completed_minutes), 0)
FROM studyhub.goals g
WHERE g.user_id = #{userId}
) AS totalCompletedMinutes,


CASE
WHEN (
SELECT COALESCE(SUM(g.target_minutes), 0)
FROM studyhub.goals g
WHERE g.user_id = #{userId}
) = 0 THEN 0
ELSE ROUND(
(
SELECT COALESCE(SUM(g.completed_minutes), 0)
FROM studyhub.goals g
WHERE g.user_id = #{userId}
) * 100.0 /
(
SELECT SUM(g.target_minutes)
FROM studyhub.goals g
WHERE g.user_id = #{userId}
), 2
)
END AS overallProgress
